import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"溫公易說 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"溫公易說 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"classics/wengong/045.md","filePath":"classics/wengong/045.md"}'),l={name:"classics/wengong/045.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><h3 id="彖曰-姤-遇也。柔遇剛也。勿用取女-不可與長也。天地相遇-品物鹹章也。剛遇中正-天下大行也。姤之時義-大矣哉。" tabindex="-1">彖曰：姤，遇也。柔遇剛也。勿用取女，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義，大矣哉。 <a class="header-anchor" href="#彖曰-姤-遇也。柔遇剛也。勿用取女-不可與長也。天地相遇-品物鹹章也。剛遇中正-天下大行也。姤之時義-大矣哉。" aria-label="Permalink to “彖曰：姤，遇也。柔遇剛也。勿用取女，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義，大矣哉。”">​</a></h3><p>剛陽德也，君子所尚也。然剛而不中則亢，剛而不正則戾。亢則人疾之，戾則人違之。故剛遇中正，然後可以大行於天下也。姤之時義，大矣哉。姤，消卦也。孔子何大焉？夫世之治亂，人之窮通，事之成敗，不可以力致也，不可以數求也，遇與不遇而已矣。舜遇堯而五典克從，百揆時敘。禹稷契皋陶遇舜而六府三事允治，地平天成。伊尹遇湯而格於皇天。師尚父遇文武而天下大定。不然泯泯於眾人之中，後世誰克知之？以是觀之，姤之為義豈不大哉。</p><h3 id="象曰-天下有風-姤。後以施命誥四方。" tabindex="-1">象曰：天下有風，姤。後以施命誥四方。 <a class="header-anchor" href="#象曰-天下有風-姤。後以施命誥四方。" aria-label="Permalink to “象曰：天下有風，姤。後以施命誥四方。”">​</a></h3><h3 id="初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅-象曰-繫於金柅-柔道牽也。" tabindex="-1">初六：繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅 象曰：繫於金柅，柔道牽也。 <a class="header-anchor" href="#初六-繫於金柅-貞吉。有攸往-見兇。羸豕孚蹢躅-象曰-繫於金柅-柔道牽也。" aria-label="Permalink to “初六：繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅 象曰：繫於金柅，柔道牽也。”">​</a></h3><h3 id="九二-包有魚-無咎。不利賓-象曰-包有魚-義不及賓也。" tabindex="-1">九二：包有魚，無咎。不利賓 象曰：包有魚，義不及賓也。 <a class="header-anchor" href="#九二-包有魚-無咎。不利賓-象曰-包有魚-義不及賓也。" aria-label="Permalink to “九二：包有魚，無咎。不利賓 象曰：包有魚，義不及賓也。”">​</a></h3><h3 id="九三-臀無膚-其行次且。厲無大咎-象曰-其行次且-行未牽也。" tabindex="-1">九三：臀無膚，其行次且。厲無大咎 象曰：其行次且，行未牽也。 <a class="header-anchor" href="#九三-臀無膚-其行次且。厲無大咎-象曰-其行次且-行未牽也。" aria-label="Permalink to “九三：臀無膚，其行次且。厲無大咎 象曰：其行次且，行未牽也。”">​</a></h3><h3 id="九四-包無魚-起兇-象曰-無魚之兇-遠民也。" tabindex="-1">九四：包無魚，起兇 象曰：無魚之兇，遠民也。 <a class="header-anchor" href="#九四-包無魚-起兇-象曰-無魚之兇-遠民也。" aria-label="Permalink to “九四：包無魚，起兇 象曰：無魚之兇，遠民也。”">​</a></h3><p>姤九四包無魚起兇，魯昭公將去季氏，宋樂祁譏之曰：政在季氏三世矣，魯君喪政四公矣。無民而能逞其志者，未之有也。國君以是鎮撫其民，魯君失民矣。靖以待命，猶可動必憂已。而昭公伐季氏，果不勝而出死於外。</p><h3 id="九五-以杞包瓜-含章-有隕自天-象曰-九五含章-中正也。有隕自天-志不捨命也。" tabindex="-1">九五：以杞包瓜，含章，有隕自天 象曰：九五含章，中正也。有隕自天，志不捨命也。 <a class="header-anchor" href="#九五-以杞包瓜-含章-有隕自天-象曰-九五含章-中正也。有隕自天-志不捨命也。" aria-label="Permalink to “九五：以杞包瓜，含章，有隕自天 象曰：九五含章，中正也。有隕自天，志不捨命也。”">​</a></h3><p>杞材之美者也，包瓜不食之物也。</p><h3 id="上九-姤其角-吝無咎-象曰-姤其角上窮-吝也。" tabindex="-1">上九：姤其角，吝無咎 象曰：姤其角上窮，吝也。 <a class="header-anchor" href="#上九-姤其角-吝無咎-象曰-姤其角上窮-吝也。" aria-label="Permalink to “上九：姤其角，吝無咎 象曰：姤其角上窮，吝也。”">​</a></h3><p>姤其角者，行無所之之謂也。</p>',13)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
